--#api tic80
--@ Vircon32 Lua TIC-80 full-size map buffer Unit Test
--@ The map is 240x136 cells, one byte each, and lives in RAM at 0x8000-0xFF7F.
--@ The buffer was 16384 words, so the init copy of the cart's <MAP> overflowed
--@ the heap and every cell past offset 0x4000 (map row 68 on) was lost:
--@ peek(0xC000..) read 0 and mget/mset beyond row 68 failed (BlasTIC's
--@ LZ-packed art lives in the high map rows). Cells here are set and read back
--@ through both mset/mget and peek/poke, low and high.
--@ Results are stored in global variables for automated memory scraping.

number_result1 = 0
number_result2 = 0
number_result3 = 0
number_result4 = 0
number_result5 = 0
number_result6 = 0
number_result7 = 0

function TIC()
    mset(10, 120, 7)
    number_result1 = mget(10, 120)                 -- Expected: 7
    number_result2 = peek(0x8000 + 120 * 240 + 10) -- Expected: 7

    poke(0x8000 + 135 * 240 + 239, 99)             -- last cell, 0xFF7F
    number_result3 = mget(239, 135)                -- Expected: 99
    number_result4 = peek(0xFF7F)                  -- Expected: 99

    poke(0xC000, 42)                               -- first cell past 0x4000
    number_result5 = peek(0xC000)                  -- Expected: 42
    number_result7 = peek(0x8000 + 120 * 240 + 50) -- Expected: 186 (<MAP> byte "ab", nibble-swapped to 0xBA by the parser)
    mset(3, 5, 11)
    number_result6 = peek(0x8000 + 5 * 240 + 3)    -- Expected: 11
end

